expect:(async () => { const A = (m, u, b) => fetch('/api' + u, { method: m, headers: { Authorization: 'Bearer ' + localStorage.getItem('erp_token'), 'Content-Type': 'application/json' }, body: b ? JSON.stringify(b) : undefined }).then(async (r) => { const t = await r.text(); return t ? JSON.parse(t) : null });
const day = new Date().toISOString().slice(0,10); const ymd=(()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')})();
const tb = async () => { const r = await A('GET', '/journals/trial-balance?from=' + ymd + '&to=' + ymd); const m = {}; for (const x of r.rows) m[x.accountCode] = Number(x.credit); return m };
const accs = await A('GET', '/accounts'); const flat = []; const walk = (l) => (l || []).forEach((a) => { flat.push(a); walk(a.children) }); walk(accs);
const ar = flat.find((a) => a.code === '108'); 
for (const o of (await A('GET', '/card-issuers')).filter((c) => c.name === 'QA회계1-카드사계정')) await A('DELETE', '/card-issuers/' + o.id);
const iss = await A('POST', '/card-issuers', { code: 'QA1D', name: 'QA회계1-카드사계정', feeRate: 0, accountId: ar.id });
const b0 = await tb();
const v = await A('POST', '/vouchers', { type: 'CARD_SALES_COLLECTION', voucherDate: ymd, method: 'CASH', cardIssuerId: iss.id, feeRate: 0, lines: [{ amount: 10000 }] });
const b1 = await tb(); await A('DELETE', '/vouchers/' + v.id); await A('DELETE', '/card-issuers/' + iss.id);
return (b1['108'] || 0) - (b0['108'] || 0) === 10000 && (b1['120'] || 0) === (b0['120'] || 0) })()
